#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Threading.Tasks;
using Cysharp.Threading.Tasks;
using MVZ2.IO;
using MVZ2.Managers;
using Newtonsoft.Json;
using PVZEngine.Tools.Unity;
using UnityEngine;
using UnityEngine.AddressableAssets;

namespace MVZ2.ResourcePacks
{
    public class ResourcePackManager : MonoBehaviour
    {
        public async Task InitResourcePacks()
        {
            // 加载所有语言包引用。
            var references = EvaluateAllResourcePackReferences();
            foreach (var reference in references)
            {
                await LoadResourcePackMetadata(reference);
            }

            // 加载启用的语言包列表。
            LoadEnabledResourcePackList();
            SaveEnabledResourcePackList();

            // 加载启用的语言包内容。
            await LoadResourcePacks();
        }
        /// <summary>
        /// 刷新语言包引用列表。
        /// 获取所有外部语言包引用，去掉不存在的，加入新添加的。
        /// 然后再次检测
        /// </summary>
        /// <returns>语言包列表是否有变动。</returns>
        public async Task<bool> RefreshLanguagePackReferences()
        {
            var references = EvaluateAllResourcePackReferences();
            var removed = resourcePackMetadatas.Keys.Except(references).ToArray();
            var added = references.Except(resourcePackMetadatas.Keys).ToArray();
            bool changed = false;
            if (removed.Count() > 0)
            {
                foreach (var remove in removed)
                {
                    RemoveLanguagePackMetadata(remove);
                }
                changed = true;
            }
            if (added.Count() > 0)
            {
                foreach (var add in added)
                {
                    await LoadResourcePackMetadata(add);
                }
                changed = true;
            }
            return changed;
        }
        public async Task ReloadLanguagePacks(ResourcePackReference[] enabled)
        {
            enabledResourcePacks.Clear();
            enabledResourcePacks.AddRange(enabled.Where(r => resourcePackMetadatas.Keys.Contains(r)));
            SaveEnabledResourcePackList();
            UnloadLanguagePacks();
            await LoadResourcePacks();
        }
        public string GetResourcePackSpriteCategory(string key)
        {
            return $"resourcepack-{key}";
        }

        #region 导入
        public string? GetImportKey(string sourcePath)
        {
            if (!File.Exists(sourcePath))
                return null;
            var fileName = Path.GetFileName(sourcePath);
            fileName = Path.ChangeExtension(fileName, $".zip");
            return fileName;
        }
        public void ImportLanguagePack(string sourcePath)
        {
            if (!File.Exists(sourcePath))
                return;
            var fileName = Path.GetFileName(sourcePath);
            fileName = Path.ChangeExtension(fileName, $".zip");
            var destPath = Path.Combine(GetExternalResourcePackDirectory(), fileName);
            FileHelper.ValidateDirectory(destPath);
            File.Copy(sourcePath, destPath);
        }
        public async Task<bool> ValidateLanguagePack(string sourcePath)
        {
            if (!File.Exists(sourcePath))
                return false;
            try
            {
                var reference = new ExternalResourcePackReference(sourcePath, false);
                var metadata = await reference.LoadMetadata(Main);
                return metadata != null;
            }
            catch (Exception)
            {
                return false;
            }
        }
        #endregion

        #region 导出
        public UniTask<bool> ExportLanguagePack(ResourcePackReference reference, string destPath)
        {
            return reference.Export(Main, destPath);
        }
        #endregion

        #region 删除
        public bool DeleteLanguagePack(ResourcePackReference reference)
        {
            return reference.Delete();
        }
        #endregion

        #region 语言包引用/元数据
        public ResourcePackMetadata? GetResourcePackMetadata(ResourcePackReference reference)
        {
            if (resourcePackMetadatas.TryGetValue(reference, out var metadata))
            {
                return metadata;
            }
            return null;
        }
        public ResourcePackReference[] GetAllResourcePackReferences()
        {
            return resourcePackMetadatas.Keys.ToArray();
        }
        private ResourcePackReference[] EvaluateAllResourcePackReferences()
        {
            List<ResourcePackReference> results = new List<ResourcePackReference>();
            results.Add(builtinResourcePackRef);

            // 外部引用。
            var dirVer0 = GetExternalResourcePackDirectoryVer0();
            var dirVer1 = GetExternalResourcePackDirectory();
            var directories = new string[] { dirVer0, dirVer1 };
            foreach (var dir in directories)
            {
                if (Directory.Exists(dir))
                {
                    // Zip语言包
                    foreach (var zip in Directory.EnumerateFiles(dir, "*.zip", SearchOption.TopDirectoryOnly))
                    {
                        results.Add(new ExternalResourcePackReference(zip, false));
                    }
                    // 文件夹语言包
                    foreach (var langDir in Directory.EnumerateDirectories(dir))
                    {
                        results.Add(new ExternalResourcePackReference(langDir, true));
                    }
                }
            }
            return results.ToArray();
        }
        private string GetExternalResourcePackDirectory()
        {
            return Path.Combine(Application.persistentDataPath, externalLangaugePackDir);
        }
        private string GetExternalResourcePackDirectoryVer0()
        {
            return Path.Combine(Application.persistentDataPath, EXTERNAL_LANGAUGE_PACK_DIR_VER_0);
        }
        private string GetEnabledResourcePackListPath()
        {
            return Path.Combine(Application.persistentDataPath, enabledPackListFileName);
        }
        private string GetEnabledResourcePackListPathVer0()
        {
            return Path.Combine(Application.persistentDataPath, ENABLED_PACK_LIST_FILE_NAME_VER_0);
        }
        private async Task LoadResourcePackMetadata(ResourcePackReference reference)
        {
            try
            {
                var metadata = await reference.LoadMetadata(Main);
                if (metadata != null)
                    resourcePackMetadatas.Add(reference, metadata);
            }
            catch (Exception e)
            {
                Debug.LogError($"加载语言包引用{reference}失败：{e}");
            }
        }
        private void RemoveLanguagePackMetadata(ResourcePackReference reference)
        {
            if (reference == null)
                return;
            var metadata = GetResourcePackMetadata(reference);
            if (metadata != null && metadata.icon)
            {
                main.ResourceManager.RemoveGeneratedTexture(metadata.icon.texture);
                main.ResourceManager.RemoveGeneratedSprite(metadata.icon, reference.GetKey(), RESOURCE_PACK_ICON_SPRITE_CATEGORY);
            }
            resourcePackMetadatas.Remove(reference);
        }
        #endregion

        #region 启用状态
        public void LoadEnabledResourcePackList()
        {
            enabledResourcePacks.Clear();
            var path = GetEnabledResourcePackListPath();
            if (File.Exists(path))
            {
                ReadEnabledResourcePackList(path);
            }
            else
            {
                var pathVer0 = GetEnabledResourcePackListPathVer0();
                ReadEnabledResourcePackList(pathVer0);
            }
            if (!enabledResourcePacks.Contains(builtinResourcePackRef))
            {
                enabledResourcePacks.Add(builtinResourcePackRef);
            }
        }
        private void ReadEnabledResourcePackList(string path)
        {
            try
            {
                using var stream = File.Open(path, FileMode.Open);
                using var reader = new StreamReader(stream);
                var json = reader.ReadToEnd();
                var packList = JsonConvert.DeserializeObject<EnabledResourcePackList>(json);
                if (packList != null)
                {
                    foreach (var key in packList.enabled)
                    {
                        var reference = resourcePackMetadatas.Keys.FirstOrDefault(r => r.GetKey() == key);
                        if (reference != null)
                        {
                            enabledResourcePacks.Add(reference);
                        }
                    }
                }
            }
            catch (Exception e)
            {
                Log.LogError($"读取启用的语言包列表失败：{e}");
            }
        }
        public void SaveEnabledResourcePackList()
        {
            try
            {
                var path = GetEnabledResourcePackListPath();
                var list = new EnabledResourcePackList();
                foreach (var reference in enabledResourcePacks)
                {
                    list.enabled.Add(reference.GetKey());
                }
                var json = JsonConvert.SerializeObject(list);
                using var stream = File.Open(path, FileMode.Create);
                using var writer = new StreamWriter(stream);
                writer.Write(json);
            }
            catch (Exception e)
            {
                Debug.LogError($"保存启用的语言包列表失败：{e}");
            }
        }
        public ResourcePackReference[] GetEnabledLanguagePackList()
        {
            return enabledResourcePacks.ToArray();
        }
        #endregion

        #region 加载语言包
        public async UniTask LoadResourcePacks()
        {
            var loadTasks = enabledResourcePacks.Select(async (reference, index) =>
            {
                var priority = enabledResourcePacks.Count - index;
                var metadata = GetResourcePackMetadata(reference);
                if (metadata == null)
                    return;
                var pack = await reference.LoadPack(Main, metadata.dataVersion);
                if (pack == null)
                    return;
                pack.Priority = priority;
                LoadLanguagePack(pack);
            });
            await UniTask.WhenAll(loadTasks);

            Main.LanguageManager.ReevaluateLanguages();
        }
        public void LoadLanguagePack(ResourcePack pack)
        {
            loadedResourcePacks.Add(pack);
            // 添加Sprite覆盖。
            AddProviders(pack);
        }
        private void AddProviders(ResourcePack pack)
        {
            Main.LanguageManager.AddCatalogProvider(pack);
            Main.ResourceManager.AddSpriteProvider(pack);
            Main.ResourceManager.AddTextureProvider(pack);
            Main.ResourceManager.AddAudioClipProvider(pack);
            Main.ResourceManager.AddSoundSourceProvider(pack);
            Main.ResourceManager.AddMusicSourceProvider(pack);
        }
        #endregion

        #region 卸载语言包
        public void UnloadLanguagePacks()
        {
            foreach (var enabledLanguagePack in loadedResourcePacks)
            {
                UnloadLanguagePack(enabledLanguagePack);
            }
            loadedResourcePacks.Clear();
        }
        public void UnloadLanguagePack(ResourcePack pack)
        {
            foreach (var pair in pack.sprites)
            {
                main.ResourceManager.RemoveGeneratedSprite(pair.Value, pair.Key.ToString(), GetResourcePackSpriteCategory(pack.Key));
            }
            foreach (var pair in pack.textures)
            {
                main.ResourceManager.RemoveGeneratedTexture(pair.Value);
            }
            foreach (var pair in pack.audioClips)
            {
                main.ResourceManager.RemoveGeneratedAudioClip(pair.Value);
            }
            RemoveProviders(pack);
            pack.DeleteTempDirectory();
        }
        private void RemoveProviders(ResourcePack pack)
        {
            Main.LanguageManager.RemoveCatalogProvider(pack);
            Main.ResourceManager.RemoveSpriteProvider(pack);
            Main.ResourceManager.RemoveTextureProvider(pack);
            Main.ResourceManager.RemoveAudioClipProvider(pack);
            Main.ResourceManager.RemoveSoundSourceProvider(pack);
            Main.ResourceManager.RemoveMusicSourceProvider(pack);
        }
        #endregion

        #region 过时
        public bool IsOutdated(int dataVersion)
        {
            return dataVersion < LATEST_DATA_VERSION;
        }
        public bool HasOutdatedEnabledPacks(IEnumerable<ResourcePackReference> references)
        {
            foreach (var reference in references)
            {
                var metadata = GetResourcePackMetadata(reference);
                if (metadata != null)
                {
                    if (IsOutdated(metadata.dataVersion))
                    {
                        return true;
                    }
                }
            }
            return false;
        }
        #endregion

        #region 加载内置
        public async Task<byte[]> LoadBuiltinBytes()
        {
            var op = Addressables.LoadAssetAsync<TextAsset>("ResourcePack");
            var textAsset = await op.Task;
            return textAsset.bytes;
        }
        #endregion

        #region 压缩ZIP
        public static void CompressLanguagePack(string sourceDirectory, string destPath)
        {
            FileHelper.ValidateDirectory(destPath);
            var sourceDirInfo = new DirectoryInfo(sourceDirectory);
            var files = Directory.GetFiles(sourceDirectory, "*", SearchOption.AllDirectories);
            using var stream = File.Open(destPath, FileMode.Create);
            using var archive = new ZipArchive(stream, ZipArchiveMode.Create);

            foreach (var filePath in files)
            {
                if (Path.GetExtension(filePath) == ".meta")
                    continue;
                var path = filePath.Replace("\\", "/");
                var entryName = Path.GetRelativePath(sourceDirectory, path);
                var entry = archive.CreateEntryFromFile(path, entryName);
            }
        }
        #endregion

        public MainManager Main => main;
        public const int LATEST_DATA_VERSION = 1;
        public const string RESOURCE_PACK_ICON_SPRITE_CATEGORY = "resource_pack_icon";
        public const string EXTERNAL_LANGAUGE_PACK_DIR_VER_0 = "language_packs";
        public const string ENABLED_PACK_LIST_FILE_NAME_VER_0 = "language_packs.json";
        [SerializeField]
        private MainManager main = null!;
        [SerializeField]
        private string externalLangaugePackDir = "resource_packs";
        [SerializeField]
        private string enabledPackListFileName = "resource_packs.json";
        private Dictionary<ResourcePackReference, ResourcePackMetadata> resourcePackMetadatas = new Dictionary<ResourcePackReference, ResourcePackMetadata>();
        private List<ResourcePackReference> enabledResourcePacks = new List<ResourcePackReference>();
        private List<ResourcePack> loadedResourcePacks = new List<ResourcePack>();
        private BuiltinResourcePackReference builtinResourcePackRef = new BuiltinResourcePackReference();
    }
}
